var cubeSize = 150;
var blockSize = 15;
var mult = 0.04;


function setup() {
	createCanvas(window.innerWidth, window.innerHeight, WEBGL);
}


function draw() {
	background(0);

	noStroke();

	push();

	translate(width / 2, height / 2, 200);
	rotateX(radians(map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, 90, -90)));
	rotateY(radians(map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, -90, 90)));

	for (let x = 0; x < cubeSize; x+=(Math.max(0.001, Math.abs(blockSize)) || 1)) {
		for (let y = 0; y < cubeSize; y+=(Math.max(0.001, Math.abs(blockSize)) || 1)) {
			for (let z = 0; z < cubeSize; z+=(Math.max(0.001, Math.abs(blockSize)) || 1)) {
				let offset = (frameCount + x) * mult + (frameCount + y) * mult - (frameCount + z) * mult;
				let wave = sin(offset);

				push();

				translate(x - cubeSize / 2, y - cubeSize / 2, z - cubeSize / 2);
				rotate(radians(map(wave, -1, 1, -180, 180)));

				fill(map(wave, -1, 1, 0, 255));

				box(wave * blockSize);

				pop();
			}
		}
	}

	pop();
}
